import { describe, expect, it } from 'vitest';
import { targetModelDiagram } from '../../../../src/domain/diagrams/target-model-diagram.js';
import { emptyDataModel } from '../../../../src/domain/planning/data-model.js';
import { targetModel } from '../../../support/data-model-fixtures.js';

// RF-623, RF-508, DEC-134: the entity-relationship diagram of the target data model is generated by
// code from the checked tables; ids are generated, every label is coded, and a foreign key is drawn
// with the cardinality its columns state (many children, one parent, or none when nullable).

const keep = (text: string): string => text;

describe('targetModelDiagram', () => {
  it('RF-623 draws the two tables, their keys and the foreign key (snapshot)', () => {
    expect(targetModelDiagram(targetModel(), keep)).toMatchInlineSnapshot(`
      "erDiagram
        e1["customer"] {
          field f1 PK "id#58; uuid"
          field f2 UK "email#58; varchar#40;200#41;"
        }
        e2["customer#95;order"] {
          field f1 PK "id#58; uuid"
          field f2 FK "customer#95;id#58; uuid"
          field f3 "status#58; varchar#40;20#41;"
          field f4 "total#58; numeric#40;10,2#41;"
        }
        e2 }o--|| e1 : "customer#95;id"
      "
    `);
  });

  it('RF-623 a nullable foreign key makes the parent optional', () => {
    const model = targetModel();
    const [parent, child] = model.tables;
    if (parent === undefined || child === undefined) throw new Error('The fixture has two tables');
    const columns = child.columns.map((column) =>
      column.name === 'customer_id' ? { ...column, nullable: true } : column,
    );

    const diagram = targetModelDiagram({ ...model, tables: [parent, { ...child, columns }] }, keep);

    expect(diagram).toContain('  e2 }o--o| e1 : "customer#95;id"\n');
  });
});

describe('targetModelDiagram: edge cases', () => {
  it('RF-623 a model without tables is the diagram header only', () => {
    expect(targetModelDiagram(emptyDataModel(null), keep)).toBe('erDiagram\n');
  });

  it('RNF-003 every name and type goes through the mask, and ids are not taken from names', () => {
    const diagram = targetModelDiagram(targetModel(), (text) => text.replaceAll('customer', 'XXX'));

    expect(diagram).not.toContain('customer');
    expect(diagram).toContain('e2["XXX#95;order"]');
    expect(diagram).toMatch(/^ {2}e2 \}o--\|\| e1 : "XXX#95;id"$/mu);
  });

  it('RF-508 a table with a hostile type still draws only coded labels', () => {
    const model = targetModel();
    const [parent] = model.tables;
    if (parent === undefined) throw new Error('The fixture has tables');
    const columns = parent.columns.map((column) => ({
      ...column,
      type: '"]\n  click e1 call alert()',
    }));

    const diagram = targetModelDiagram({ ...model, tables: [{ ...parent, columns }] }, keep);

    expect(diagram.trimEnd().split('\n')).toHaveLength(5);
    expect(diagram).not.toMatch(/^\s*click/mu);
  });
});
